/* Tick bars — 2/6 Task segments (card-design) & volume bars (datatable-003) */
export function TickBars({
  total,
  filled,
  tone = "green",
  size = "md",
  className,
}: {
  total: number;
  filled: number;
  tone?: "green" | "gray" | "red";
  size?: "sm" | "md" | "lg";
  className?: string;
}) {
  const dims =
    size === "lg"
      ? "w-[5px] h-5 rounded-[2.5px]"
      : size === "md"
        ? "w-1 h-4 rounded-[2px]"
        : "w-[3px] h-3 rounded-[1.5px]";
  const fill =
    tone === "green"
      ? "bg-emerald-500"
      : tone === "red"
        ? "bg-red-500"
        : "bg-ink-3";
  return (
    <span className={cx("inline-flex items-center gap-[3px]", className)}>
      {Array.from({ length: total }, (_, i) => (
        <span
          key={i}
          className={cx(
            dims,
            i < filled ? fill : "bg-ink/12 dark:bg-white/12",
